import { DateTime } from 'luxon';

export interface Clock {
  now(): DateTime;
}

export class RealClock implements Clock {
  now(): DateTime {
    return DateTime.now();
  }
}

import { DateTime } from 'luxon';
import { Clock } from '../clock/clock.js';

export class ControllableClock implements Clock {
  private currentTime: DateTime;

  constructor(initialTime: string | DateTime = '2026-10-13T09:00:00-03:00') {
    this.currentTime = typeof initialTime === 'string' 
      ? DateTime.fromISO(initialTime) 
      : initialTime;
  }

  now(): DateTime {
    return this.currentTime;
  }

  set(time: string | DateTime): void {
    this.currentTime = typeof time === 'string'
      ? DateTime.fromISO(time)
      : time;
  }
}

import Database from 'better-sqlite3';
import path from 'path';
import fs from 'fs';

export function createDatabase(dbPath?: string): Database.Database {
  let resolvedPath = dbPath;
  if (!resolvedPath) {
    const isTest = process.env.NODE_ENV === 'test' || process.env.VITEST;
    if (isTest) {
      resolvedPath = ':memory:';
    } else {
      const dataDir = path.resolve(process.cwd(), 'data');
      if (!fs.existsSync(dataDir)) {
        fs.mkdirSync(dataDir, { recursive: true });
      }
      resolvedPath = path.join(dataDir, 'database.sqlite');
    }
  }

  const db = new Database(resolvedPath);
  db.pragma('foreign_keys = ON');
  return db;
}

import Database from 'better-sqlite3';

export function runMigrations(db: Database.Database): void {
  db.exec(`
    CREATE TABLE IF NOT EXISTS usuarios (
      id TEXT PRIMARY KEY,
      nome TEXT NOT NULL,
      papel TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS salas (
      id TEXT PRIMARY KEY,
      nome TEXT NOT NULL,
      capacidade INTEGER NOT NULL
    );

    CREATE TABLE IF NOT EXISTS atividades (
      id TEXT PRIMARY KEY,
      titulo TEXT NOT NULL,
      tipo TEXT NOT NULL,
      sala_id TEXT NOT NULL,
      vagas INTEGER NOT NULL,
      carga_horaria_minutos INTEGER NOT NULL,
      situacao TEXT NOT NULL,
      FOREIGN KEY (sala_id) REFERENCES salas(id)
    );

    CREATE TABLE IF NOT EXISTS encontros (
      id TEXT PRIMARY KEY,
      atividade_id TEXT NOT NULL,
      inicio TEXT NOT NULL,
      fim TEXT NOT NULL,
      FOREIGN KEY (atividade_id) REFERENCES atividades(id)
    );

    CREATE TABLE IF NOT EXISTS relogio_estado (
      id INTEGER PRIMARY KEY CHECK (id = 1),
      agora TEXT NOT NULL
    );
  `);
}

import Database from 'better-sqlite3';

export function runSeed(db: Database.Database): void {
  const insertUsuario = db.prepare('INSERT OR REPLACE INTO usuarios (id, nome, papel) VALUES (?, ?, ?)');
  const usuarios = [
    ['org-ana', 'Ana Beatriz Lima', 'organizacao'],
    ['org-bruno', 'Bruno Tavares', 'organizacao'],
    ['p-carla', 'Carla Mendes Souza', 'participante'],
    ['p-diego', 'Diego Alves', 'participante'],
    ['p-elisa', 'Elisa Fernandes da Rocha', 'participante'],
    ['p-fabio', 'Fábio Nogueira', 'participante'],
    ['p-gabriela', 'Gabriela Moura Castro', 'participante'],
    ['p-heitor', 'Heitor Campos', 'participante'],
    ['p-isadora', 'Isadora Ribeiro dos Santos', 'participante'],
    ['p-joao', 'João Pedro Martins', 'participante']
  ];

  const insertSala = db.prepare('INSERT OR REPLACE INTO salas (id, nome, capacidade) VALUES (?, ?, ?)');
  const salas = [
    ['auditorio', 'Auditório Central', 200],
    ['sala-101', 'Sala 101', 40],
    ['sala-102', 'Sala 102', 40],
    ['lab-3', 'Laboratório 3', 20]
  ];

  const insertRelogio = db.prepare('INSERT OR REPLACE INTO relogio_estado (id, agora) VALUES (1, ?)');

  db.transaction(() => {
    for (const u of usuarios) {
      insertUsuario.run(u[0], u[1], u[2]);
    }
    for (const s of salas) {
      insertSala.run(s[0], s[1], s[2]);
    }
    insertRelogio.run('2026-10-13T09:00:00-03:00');
  })();
}

export interface M2IntegrationPort {
  getOcupadas(atividadeId: string): number;
  getEmEspera(atividadeId: string): number;
}

export class NeutralM2Adapter implements M2IntegrationPort {
  getOcupadas(_atividadeId: string): number {
    return 0;
  }

  getEmEspera(_atividadeId: string): number {
    return 0;
  }
}

import express, { Request, Response, NextFunction } from 'express';
import cors from 'cors';
import { createDatabase } from './db/connection.js';
import { runMigrations } from './db/migrate.js';
import { runSeed } from './db/seed.js';
import { NeutralM2Adapter } from './integrations/m2-port.js';

export function createApp(dbPath?: string) {
  const app = express();

  app.use(cors({
    origin: '*',
    allowedHeaders: ['Content-Type', 'X-Usuario']
  }));
  app.use(express.json());

  const db = createDatabase(dbPath);
  runMigrations(db);
  runSeed(db);

  const m2Port = new NeutralM2Adapter();

  // Modo de teste routes (when MODO_TESTE=1)
  if (process.env.MODO_TESTE === '1') {
    app.post('/_teste/reset', (_req: Request, res: Response) => {
      runSeed(db);
      res.status(204).send();
    });

    app.get('/_teste/relogio', (_req: Request, res: Response) => {
      const row = db.prepare('SELECT agora FROM relogio_estado WHERE id = 1').get() as { agora: string };
      res.json({ agora: row ? row.agora : '2026-10-13T09:00:00-03:00' });
    });

    app.put('/_teste/relogio', (req: Request, res: Response) => {
      const { agora } = req.body;
      if (!agora) {
        res.status(422).json({ erro: 'DADOS_INVALIDOS', mensagem: 'Campo agora é obrigatório' });
        return;
      }
      db.prepare('UPDATE relogio_estado SET agora = ? WHERE id = 1').run(agora);
      res.json({ agora });
    });
  } else {
    app.all('/_teste/*', (_req: Request, res: Response) => {
      res.status(404).json({ erro: 'NAO_ENCONTRADO', mensagem: 'Modo de teste desativado' });
    });
  }

  // Middleware de autenticação X-Usuario para rotas protegidas (exceto /_teste/* e GET /certificados/:codigo)
  const requireUser = (req: Request, res: Response, next: NextFunction) => {
    const usuarioId = req.headers['x-usuario'] as string;
    if (!usuarioId) {
      res.status(401).json({ erro: 'USUARIO_DESCONHECIDO', mensagem: 'Cabeçalho X-Usuario ausente' });
      return;
    }
    const user = db.prepare('SELECT id, nome, papel FROM usuarios WHERE id = ?').get(usuarioId);
    if (!user) {
      res.status(401).json({ erro: 'USUARIO_DESCONHECIDO', mensagem: 'Usuário desconhecido' });
      return;
    }
    (req as any).user = user;
    next();
  };

  // GET /salas (todos)
  app.get('/salas', (_req: Request, res: Response) => {
    const salas = db.prepare('SELECT id, nome, capacidade FROM salas').all();
    res.json(salas);
  });

  // GET /atividades (todos)
  app.get('/atividades', (_req: Request, res: Response) => {
    const atividades = db.prepare('SELECT id, titulo, tipo, sala_id as salaId, vagas, carga_horaria_minutos as cargaHorariaMinutos, situacao FROM atividades').all();
    const result = atividades.map((atv: any) => ({
      ...atv,
      ocupadas: m2Port.getOcupadas(atv.id),
      vagasRestantes: atv.vagas - m2Port.getOcupadas(atv.id),
      emEspera: m2Port.getEmEspera(atv.id),
      encontros: db.prepare('SELECT id, inicio, fim FROM encontros WHERE atividade_id = ?').all(atv.id)
    }));
    res.json(result);
  });

  // 404 handler for unknown routes adhering to contract error format
  app.use((_req: Request, res: Response) => {
    res.status(404).json({ erro: 'NAO_ENCONTRADO', mensagem: 'Recurso não encontrado' });
  });

  // Error handling middleware
  app.use((err: any, _req: Request, res: Response, _next: NextFunction) => {
    res.status(422).json({ erro: 'DADOS_INVALIDOS', mensagem: err.message || 'Erro de validação' });
  });

  return app;
}

